$error = ''; $success = ''; $preview = $_SESSION['historical_generator_preview'] ?? null;
function htg_h(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function htg_date(string $v): DateTimeImmutable {
    $d = DateTimeImmutable::createFromFormat('!Y-m-d H:i:s', $v . ' 00:00:00');
    $e = DateTimeImmutable::getLastErrors();
    if (!$d || ($e !== false && ($e['warning_count'] || $e['error_count']))) throw new RuntimeException('Enter valid calendar dates.');
    return $d;
}
function htg_branch(int $id): array {
    $rows = db_query("SELECT id, branch_name FROM branches WHERE id = ? AND status != 'Archived' LIMIT 1", 'i', [$id]) ?: [];
    if (!$rows) throw new RuntimeException('Select a valid active branch.'); return $rows[0];
}
function htg_catalog(string $table): array {
    if ($table === 'products') return db_query("SELECT product_id AS id, name, price FROM products WHERE LOWER(TRIM(product_type))='fixed' AND LOWER(TRIM(COALESCE(status,''))) NOT IN ('archived','inactive') ORDER BY product_id") ?: [];
    return db_query("SELECT service_id AS id, name, category, COALESCE(price,0) AS price FROM services WHERE status='Activated' ORDER BY service_id") ?: [];
}
function htg_schema_ready(): bool {
    foreach ([['orders','customer_id'],['orders','branch_id'],['orders','reference_id'],['orders','total_amount'],['orders','status'],['orders','payment_status'],['orders','payment_method'],['orders','payment_reference'],['orders','order_date'],['orders','updated_at'],['orders','notes'],['orders','pos_guest_display_name'],['orders','pos_guest_email'],['order_items','customization_data'],['inventory_transactions','transaction_date'],['inventory_transactions','transaction_id']] as $f) if (!db_table_has_column($f[0],$f[1])) return false;
    return true;
}
function htg_material_plan(string $serviceType, int $quantity): array {
    $rules = db_query("SELECT r.item_id, r.rule_type, i.name, i.track_by_roll, i.unit_of_measure
                       FROM service_material_rules r
                       JOIN inv_items i ON i.id = r.item_id
                       WHERE r.service_type = ? ORDER BY r.item_id", 's', [$serviceType]) ?: [];
    $materials = [];
    foreach ($rules as $rule) {
        if ((int)($rule['track_by_roll'] ?? 0) === 1) {
            throw new RuntimeException('Service "' . $serviceType . '" uses roll material and needs a configured historical dimension before it can be generated safely.');
        }
        $materials[] = [
            'item_id' => (int)$rule['item_id'],
            'quantity' => max(1, $quantity),
            'uom' => (string)($rule['unit_of_measure'] ?? 'pcs'),
            'computed_len' => 0,
        ];
    }
    return ['materials' => $materials, 'label' => $materials ? implode(', ', array_map(static fn($m) => 'material #' . (int)$m['item_id'] . ' x ' . (float)$m['quantity'], $materials)) : 'No configured material rules'];
}
function htg_insert(array $r, string $token, string $reason): int {
    global $conn;
    $guest = printflow_pos_resolve_checkout_customer_context(['customer_id'=>'guest','guest_display_name'=>'Historical Walk-in','customer_email'=>'']);
    $total = round((float)$r['unit_price'] * (int)$r['quantity'], 2);
    $note = '[Historical generator] Entered by user #' . (int)get_user_id() . ' at ' . date('Y-m-d H:i:s') . '. Business date: ' . $r['business_at'] . '. Reason: ' . $reason;
    $cols=['customer_id','pos_guest_display_name','pos_guest_email','branch_id','reference_id','total_amount','status','payment_status','payment_method','payment_reference','order_date','notes'];
    $vals=[(int)$guest['customer_id'],'Historical Walk-in','',(int)$r['branch_id'],'HGEN-'.$token,$total,$r['type']==='custom'?'Pending':'Completed','Paid','Cash','HGEN-'.$token,$r['business_at'],$note]; $types='issisdssssss';
    foreach ([['amount_paid','d',$total],['order_type','s',$r['type']],['order_source','s','historical_generator']] as $o) if (db_table_has_column('orders',$o[0])) { $cols[]=$o[0];$vals[]=$o[2];$types.=$o[1]; }
    if (!db_execute('INSERT INTO orders ('.implode(',',$cols).') VALUES ('.implode(',',array_fill(0,count($cols),'?')).')',$types,$vals)) throw new RuntimeException('Generated order creation failed.');
    $oid=(int)$conn->insert_id; if (!db_execute('UPDATE orders SET updated_at=NOW() WHERE order_id=?','i',[$oid])) throw new RuntimeException('Generated order audit timestamp failed.');
    $json=json_encode($r['customization'] ?? [],JSON_UNESCAPED_SLASHES);
    if ($json===false || !db_execute('INSERT INTO order_items (order_id,product_id,quantity,unit_price,customization_data) VALUES (?,?,?,?,?)','iiids',[$oid,(int)$r['product_id'],(int)$r['quantity'],(float)$r['unit_price'],$json])) throw new RuntimeException('Generated item creation failed.');
    $item=(int)$conn->insert_id;
    if ($r['type']==='ready') { printflow_apply_product_order_item_inventory($item,(int)$r['branch_id'],(int)get_user_id(),'Historical generated sale',$r['business_at']); return $oid; }
    if (!db_execute('INSERT INTO customizations (order_id,order_item_id,customer_id,service_type,customization_details,status,created_at,updated_at) VALUES (?,?,?,?,?,?,NOW(),NOW())','iiisss',[$oid,$item,(int)$guest['customer_id'],$r['service_name'],$json,'In Production'])) throw new RuntimeException('Generated customization creation failed.');
    $job=JobOrderService::createOrder(['order_id'=>$oid,'order_item_id'=>$item,'customer_id'=>(int)$guest['customer_id'],'branch_id'=>(int)$r['branch_id'],'job_title'=>$r['service_name'],'service_type'=>$r['service_type'],'quantity'=>(int)$r['quantity'],'estimated_total'=>$total,'notes'=>$reason.' Planned production: '.$r['production_at'].'; planned completion: '.$r['completion_at'],'priority'=>'NORMAL','created_by'=>(int)get_user_id()],[]);
    if ((int)$job<=0) throw new RuntimeException('Generated production job creation failed.');
    $materialPlan = htg_material_plan((string)$r['service_type'], (int)$r['quantity']);
    foreach ($materialPlan['materials'] as $material) {
        JobOrderService::addMaterial((int)$job, (int)$material['item_id'], (float)$material['quantity'], (string)$material['uom'], null, 'Historical generator assignment', null, 'JOB');
    }
    JobOrderService::processHistoricalProductionDeductions((int)$job, (string)$r['production_at']);
    return $oid;
}
function htg_preview(string $start,string $end,int $branch,int $count,int $readyPct,int $customPct,array $products,array $services,string $reason): array {
    if ($customPct > 0) foreach ($services as $service) {
        htg_material_plan(JobOrderService::inferServiceTypeFromProduct((string)$service['category'], (string)$service['name']), 1);
    }
    $from=htg_date($start);$to=htg_date($end)->setTime(23,59,59);if($from>$to||$to>new DateTimeImmutable('now'))throw new RuntimeException('The date range must end today or earlier.');if($count<1||$count>500)throw new RuntimeException('Transactions must be between 1 and 500.');if($readyPct+$customPct!==100)throw new RuntimeException('Percentages must total 100.');if($readyPct&&!$products)throw new RuntimeException('No active products are available.');if($customPct&&!$services)throw new RuntimeException('No active services are available.');if($customPct&&!db_query("SELECT product_id FROM products WHERE sku='POS-SERVICE' LIMIT 1"))throw new RuntimeException('The existing POS service placeholder product is missing.');
    $stock=[];foreach($products as $p){$pid=(int)$p['id'];$opts=printflow_product_option_stock_map($pid,$branch);if($opts)foreach($opts as $o)$stock[$pid.'|'.$o['option_value']]=(int)$o['stock_quantity'];else{[$n]=printflow_product_effective_stock($pid,$branch);$stock[$pid.'|']=(int)$n;}}
    $times=[];$span=$to->getTimestamp()-$from->getTimestamp();for($i=0;$i<$count;$i++)$times[]=$from->getTimestamp()+($span?random_int(0,$span):0);sort($times);$target=(int)round($count*$readyPct/100);$rows=[];$ready=0;$custom=0;
    foreach($times as $ts){$isReady=$ready<$target&&($custom>=$count-$target||random_int(0,1));if($isReady){$choices=[];foreach($products as $p){$pid=(int)$p['id'];$opts=printflow_product_option_stock_map($pid,$branch);if($opts)foreach($opts as $o)if(($stock[$pid.'|'.$o['option_value']]??0)>0)$choices[]=['p'=>$p,'o'=>$o];elseif(($stock[$pid.'|']??0)>0)$choices[]=['p'=>$p,'o'=>null];}if(!$choices)throw new RuntimeException('Current branch stock cannot support this preview.');$c=$choices[array_rand($choices)];$key=(int)$c['p']['id'].'|'.($c['o']['option_value']??'');$q=min(random_int(1,3),max(1,(int)$stock[$key]));$stock[$key]-=$q;$customization=[];if($c['o']){$customization[$c['o']['field_key']]=$c['o']['option_value'];$customization[$c['o']['field_label']]=$c['o']['option_value'];}$rows[]=['type'=>'ready','business_at'=>date('Y-m-d H:i:s',$ts),'production_at'=>'-','completion_at'=>'-','branch_id'=>$branch,'branch_name'=>$b['branch_name'],'name'=>$c['p']['name'],'product_id'=>(int)$c['p']['id'],'quantity'=>$q,'unit_price'=>(float)$c['p']['price'],'total'=>(float)$c['p']['price']*$q,'customization'=>$customization,'expected_usage'=>'Ready-made stock: '.$q.' pcs'];$ready++;}else{$s=$services[array_rand($services)];$at=new DateTimeImmutable(date('Y-m-d H:i:s',$ts));$prod=$at->modify('+' . random_int(1,3) . ' days');$now=new DateTimeImmutable('now');if($prod>$now)$prod=$now;$done=$prod->modify('+' . random_int(0,2) . ' days');if($done>$now)$done=$now;$ph=db_query("SELECT product_id FROM products WHERE sku='POS-SERVICE' LIMIT 1")?:[];$rows[]=['type'=>'custom','business_at'=>$at->format('Y-m-d H:i:s'),'production_at'=>$prod->format('Y-m-d H:i:s'),'completion_at'=>$done->format('Y-m-d H:i:s'),'branch_id'=>$branch,'branch_name'=>$b['branch_name'],'name'=>$s['name'],'service_name'=>$s['name'],'service_type'=>JobOrderService::inferServiceTypeFromProduct((string)$s['category'],(string)$s['name']),'product_id'=>(int)($ph[0]['product_id']??0),'quantity'=>1,'unit_price'=>(float)$s['price'],'total'=>(float)$s['price'],'customization'=>['source'=>'HISTORICAL_GENERATOR','service_id'=>(int)$s['id'],'service_type'=>$s['name'],'specifications'=>'Historical walk-in service transaction from existing service catalog.'],'expected_usage'=>'Configured non-roll service material rules; deducted on production date.'];$custom++;}}
    if(count($rows)!==$count)throw new RuntimeException('The requested mix cannot be generated from current stock.');usort($rows,static fn($a,$b)=>strcmp($a['business_at'],$b['business_at']));return ['token'=>bin2hex(random_bytes(24)),'expires_at'=>time()+900,'start'=>$start,'end'=>$end,'branch_id'=>$branch,'branch_name'=>$b['branch_name'],'reason'=>$reason,'rows'=>$rows];
}
$csrf=function_exists('generate_csrf_token')?generate_csrf_token():($_SESSION['csrf_token']??'');$today=date('Y-m-d');$branches=db_query("SELECT id,branch_name FROM branches WHERE status!='Archived' ORDER BY branch_name")?:[];$old=$_POST;
ob_start(static function (string $html): string { return str_replace('name="reason" required', 'name="reason"', $html); });
if($_SERVER['REQUEST_METHOD']==='POST')try{if(!verify_csrf_token($_POST['csrf_token']??''))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'preview');if($action==='preview'){$reason=trim((string)($_POST['reason']??''));if(strlen($reason)>1000)throw new RuntimeException('Enter a reason of 1,000 characters or fewer.');$preview=htg_preview((string)($_POST['start_date']??''),(string)($_POST['end_date']??''),(int)($_POST['branch_id']??0),(int)($_POST['transaction_count']??0),(int)($_POST['ready_pct']??0),(int)($_POST['custom_pct']??0),htg_catalog('products'),htg_catalog('services'),$reason);$_SESSION['historical_generator_preview']=$preview;}elseif($action==='confirm'){$token=trim((string)($_POST['preview_token']??''));$preview=$_SESSION['historical_generator_preview']??null;if(!$preview||!hash_equals((string)$preview['token'],$token)||(int)$preview['expires_at']<time())throw new RuntimeException('Preview expired. Generate a new preview.');if(isset($_SESSION['historical_generator_used'][$token]))throw new RuntimeException('This preview was already processed.');if(!htg_schema_ready())throw new RuntimeException('Required order or inventory fields are missing.');$conn->begin_transaction();$ids=[];try{foreach($preview['rows'] as $r)$ids[]=htg_insert($r,$token.'-'.count($ids),$preview['reason']);if(!$conn->commit())throw new RuntimeException('Batch commit failed.');}catch(Throwable $e){if(printflow_db_in_transaction($conn))$conn->rollback();throw $e;}$_SESSION['historical_generator_used'][$token]=true;$_SESSION['historical_generator_preview']=null;log_activity((int)get_user_id(),'Historical transaction batch generated',json_encode(['orders'=>$ids,'preview_token'=>$token,'real_processed_at'=>date('Y-m-d H:i:s')],JSON_UNESCAPED_SLASHES));$success='Generated '.count($ids).' historical transaction(s).';$preview=null;}else throw new RuntimeException('Invalid action.');}catch(Throwable $e){$error=$e->getMessage();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historical Transaction Generator</title><style>body{font-family:Arial;background:#f4f7f9;color:#173047;margin:0}.wrap{max-width:1180px;margin:30px auto;padding:20px}.panel{background:#fff;border:1px solid #d9e2e8;border-radius:10px;padding:24px;margin:18px 0}.notice,.warning,.error,.success{padding:14px;border-radius:7px;margin:14px 0}.notice{background:#fff7d6}.warning{background:#eaf4ff}.error{background:#ffe6e6;color:#a21919}.success{background:#e5f8eb;color:#176b35}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}label{font-weight:700;font-size:13px;display:flex;flex-direction:column;gap:6px}input,select,textarea{font:inherit;padding:10px;border:1px solid #b8c9d4;border-radius:6px}textarea{min-height:70px}button{padding:11px 16px;border:0;border-radius:6px;background:#0b6174;color:#fff;font-weight:700}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:9px;border-bottom:1px solid #e2e9ee;text-align:left}th{background:#f3f7f9}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Historical Transaction Generator</h1><p>Admin-only preview tool for historical walk-in transactions.</p><div class="notice"><strong>Use this page only for real historical business transactions.</strong> Stock will be deducted from current inventory. Enter transactions from oldest to newest.</div><?php if($error):?><div class="error"><?=htg_h($error)?></div><?php endif;?><?php if($success):?><div class="success"><?=htg_h($success)?></div><?php endif;?><section class="panel"><form method="post"><input type="hidden" name="csrf_token" value="<?=htg_h((string)$csrf)?>"><div class="grid"><label>Start Date<input type="date" name="start_date" max="<?=$today?>" value="<?=htg_h((string)($old['start_date']??$today))?>" required></label><label>End Date<input type="date" name="end_date" max="<?=$today?>" value="<?=htg_h((string)($old['end_date']??$today))?>" required></label><label>Branch<select name="branch_id" required><option value="">Select branch</option><?php foreach($branches as $b):?><option value="<?=htg_h((string)$b['id'])?>"><?=htg_h((string)$b['branch_name'])?></option><?php endforeach;?></select></label><label>Number of Transactions<input type="number" name="transaction_count" min="1" max="500" value="10" required></label><label>Ready-Made %<input type="number" name="ready_pct" min="0" max="100" value="100" required></label><label>Custom/Service %<input type="number" name="custom_pct" min="0" max="100" value="0" required></label><label>Reason / Note<textarea name="reason" required>Historical transaction backfill</textarea></label></div><p>Walk-in customer only · Cash only · Paid only</p><button name="action" value="preview">Generate Preview</button></form></section><?php if(is_array($preview)&&!empty($preview['rows'])):?><section class="panel"><h2>Preview (nothing has been saved)</h2><div style="overflow:auto"><table><tr><th>Date/time</th><th>Type</th><th>Product/service</th><th>Qty</th><th>Total</th><th>Production</th><th>Expected usage</th></tr><?php foreach($preview['rows'] as $r):?><tr><td><?=htg_h($r['business_at'])?></td><td><?=htg_h($r['type'])?></td><td><?=htg_h($r['name'])?></td><td><?=htg_h((string)$r['quantity'])?></td><td>PHP <?=number_format((float)$r['total'],2)?></td><td><?=htg_h($r['production_at'])?></td><td><?=htg_h($r['expected_usage'])?></td></tr><?php endforeach;?></table></div><form method="post" onsubmit="return confirm('Generate this exact preview?');"><input type="hidden" name="csrf_token" value="<?=htg_h((string)$csrf)?>"><input type="hidden" name="preview_token" value="<?=htg_h($preview['token'])?>"><button name="action" value="confirm">Confirm and Generate</button></form><p class="warning">Custom/service rows create paid pending jobs and keep material deductions on the normal production workflow. The current job API does not expose a separate historical production timestamp.</p></section><?php endif;?></main></body></html>
